// ============================================================
// Merge: HttpClientConfig
// ============================================================
// MergeHttpClientConfig fills zero-valued fields in dst from src.
func MergeHttpClientConfig(dst, src *HttpClientConfig) {
	if !dst.DisableKeepAlives {
		dst.DisableKeepAlives = src.DisableKeepAlives
	}
	if len(dst.RootCerts) == 0 {
		dst.RootCerts = src.RootCerts
	}
	if dst.ClientCert == nil {
		dst.ClientCert = src.ClientCert
	}
	if dst.TimeoutSeconds == 0 {
		dst.TimeoutSeconds = src.TimeoutSeconds
	}
	if dst.MaxIdleConns == 0 {
		dst.MaxIdleConns = src.MaxIdleConns
	}
	if dst.MaxIdleConnsPerHost == 0 {
		dst.MaxIdleConnsPerHost = src.MaxIdleConnsPerHost
	}
	if dst.IdleConnTimeoutSeconds == 0 {
		dst.IdleConnTimeoutSeconds = src.IdleConnTimeoutSeconds
	}
	if dst.TlsHandshakeTimeoutSeconds == 0 {
		dst.TlsHandshakeTimeoutSeconds = src.TlsHandshakeTimeoutSeconds
	}
	if dst.ExpectContinueTimeoutSeconds == 0 {
		dst.ExpectContinueTimeoutSeconds = src.ExpectContinueTimeoutSeconds
	}
	if dst.ResponseHeaderTimeoutSeconds == 0 {
		dst.ResponseHeaderTimeoutSeconds = src.ResponseHeaderTimeoutSeconds
	}
	if dst.RetryConfig == nil {
		dst.RetryConfig = src.RetryConfig
	} else if src.RetryConfig != nil {
		MergeRetryConfig(dst.RetryConfig, src.RetryConfig)
	}
}

// ============================================================
// Merge: RetryConfig
// ============================================================
// MergeRetryConfig fills zero-valued fields in dst from src.
func MergeRetryConfig(dst, src *RetryConfig) {
	if dst.MaxRetries == 0 {
		dst.MaxRetries = src.MaxRetries
	}
	if dst.InitialBackoffMs == 0 {
		dst.InitialBackoffMs = src.InitialBackoffMs
	}
	if dst.MaxBackoffMs == 0 {
		dst.MaxBackoffMs = src.MaxBackoffMs
	}
	if dst.BackoffMultiplier == 0 {
		dst.BackoffMultiplier = src.BackoffMultiplier
	}
	if len(dst.RetryableStatusCodes) == 0 {
		dst.RetryableStatusCodes = src.RetryableStatusCodes
	}
}
